from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from .models import CloudAsset

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def batch_tag_cloud_assets(request):
    subset_spec = request.data.get('match_tags')
    applied_tags = request.data.get('applied_tags')

    if not isinstance(subset_spec, dict) or not isinstance(applied_tags, dict):
        return Response({'error': 'match_tags and applied_tags must be JSON dicts'}, status=status.HTTP_400_BAD_REQUEST)

    updated_count = CloudAsset.objects.filter(
        organization=request.user.organization,
        asset_metadata__contained_by=subset_spec
    ).update(operational_status=applied_tags.get('status', 'ACTIVE'))

    return Response({'updated_count': updated_count})
